/**
 * The head is drawn facing +x in its own space, then mirrored and rotated onto
 * the spine's opening tangent (≈20.6°) so it looks back over the body.
 */
function DragonHead() {
  return (
    <g transform="translate(90,225) rotate(20.6) scale(-1,1)">
      {/* horns, swept back along the body */}
      <path
        d="M6,-20C-16,-34 -40,-40 -62,-32C-44,-32 -26,-26 -12,-15Z"
        fill="currentColor"
        opacity=".85"
      />
      <path
        d="M2,-14C-20,-23 -46,-24 -66,-13C-46,-17 -24,-13 -8,-6Z"
        fill="currentColor"
        opacity=".7"
      />
      {/* mane */}
      <path
        d="M-2,-18C-14,-30 -30,-36 -46,-36C-32,-28 -22,-18 -16,-6Z"
        fill="currentColor"
        opacity=".55"
      />
      {/* lower jaw */}
      <path
        d="M18,10C34,15 52,18 68,12C63,21 50,27 34,27C26,27 20,20 18,16Z"
        fill="currentColor"
      />
      {/* skull + snout */}
      <path
        d="M0,-24C24,-31 52,-29 68,-15C75,-9 80,-4 80,0C80,4 75,6 68,6L34,10C22,11 12,15 0,17Z"
        fill="currentColor"
      />
      {/* brow ridge */}
      <path
        d="M26,-19C35,-26 49,-26 58,-19"
        fill="none"
        stroke="var(--color-sumi)"
        strokeWidth="2.5"
        strokeLinecap="round"
        opacity=".55"
      />
      {/* eye */}
      <ellipse cx="41" cy="-9" rx="6.5" ry="4.5" fill="var(--color-sumi)" />
      <circle cx="42.5" cy="-9.5" r="1.8" fill="var(--color-yamabuki)" />
      {/* nostril */}
      <circle cx="71" cy="-3" r="2" fill="var(--color-sumi)" opacity=".7" />
      {/* whiskers — long, trailing back over the body */}
      <path
        d="M74,3C42,28 -12,32 -58,17"
        fill="none"
        stroke="currentColor"
        strokeWidth="2.6"
        strokeLinecap="round"
        opacity=".8"
      />
      <path
        d="M72,-6C46,-26 2,-32 -46,-21"
        fill="none"
        stroke="currentColor"
        strokeWidth="2.2"
        strokeLinecap="round"
        opacity=".65"
      />
    </g>
  );
}

/** A four-clawed foot, the mark of a Japanese (rather than Chinese) dragon. */
function Claw({ x, y, r = 0 }: { x: number; y: number; r?: number }) {
  return (
    <g transform={`translate(${x},${y}) rotate(${r})`} fill="currentColor">
      <path d="M0,0C6,10 10,20 8,30C14,26 20,28 24,34C22,24 18,12 10,4Z" opacity=".9" />
      <path
        d="M8,30C4,36 6,42 12,44M12,32C10,40 14,45 20,45M18,32C18,40 22,44 28,42"
        fill="none"
        stroke="currentColor"
        strokeWidth="2.4"
        strokeLinecap="round"
      />
    </g>
  );
}

type DragonProps = {
  className?: string;
  /** "solid" paints the serpent; "stroke" draws it as a single ink line. */
  variant?: "solid" | "stroke";
  /** Adds the class the reveal observer uses to animate the stroke on. */
  drawOnReveal?: boolean;
};

export function Dragon({
  className,
  variant = "solid",
  drawOnReveal = false,
}: DragonProps) {
  if (variant === "stroke") {
    return (
      <svg
        viewBox="0 0 1400 420"
        className={className}
        fill="none"
        aria-hidden="true"
        focusable="false"
        preserveAspectRatio="xMidYMid meet"
      >
        <path
          d={SPINE}
          stroke="currentColor"
          strokeWidth="3"
          strokeLinecap="round"
          className={drawOnReveal ? "draw-path" : undefined}
          style={drawOnReveal ? ({ "--len": 3600 } as React.CSSProperties) : undefined}
        />
      </svg>
    );
  }

  return (
    <svg
      viewBox="0 0 1400 420"
      className={className}
      aria-hidden="true"
      focusable="false"
      preserveAspectRatio="xMidYMid meet"
    >
      <g fill="currentColor">
        <Claw x={300} y={296} r={-8} />
        <Claw x={700} y={158} r={-14} />
        <path d={BODY} />
        <path d={SPIKES} fill="none" stroke="currentColor" strokeWidth="3.5" strokeLinecap="round" />
        <DragonHead />
      </g>
      {/* belly scutes — a lighter ripple along the underside */}
      <path
        d={SPINE}
        fill="none"
        stroke="var(--color-sumi)"
        strokeWidth="1.5"
        strokeDasharray="3 12"
        opacity=".28"
      />
    </svg>
  );
}

/** Just the spine, exported for the scroll-progress rail. */
export const DRAGON_SPINE = SPINE;
